      "duration": 0.1
    },
    {
      "keystrokes": "python3 - <<'PY'
from pathlib import Path
seqs={}
name=None
for line in Path('sequences.fasta').read_text().splitlines():
    if line.startswith('>'):
        name=line[1:].strip(); seqs[name]=''
    elif line.strip():
        seqs[name]+=line.strip().upper()
for k,v in seqs.items():
    print(k,len(v))
    for site in ['GGTCTC','GAGACC']:
        print(' ',site, [i+1 for i in range(len(v)-5) if v[i:i+6]==site])
PY
",
      "duration": 0.1
    }
  ],
