use strict;
use warnings;

# Parse sequences
my %s; my $n;
open my $F, '<', 'sequences.fasta' or die $!;
while (<$F>) { chomp; if (/^>(\S+)/) { $n = $1 } else { $s{$n} .= uc($_) } }
close $F;

sub rev_comp {
  my $seq = shift;
  my $comp = reverse($seq);
  $comp =~ tr/ACGT/TGCA/;
  return $comp;
}

sub oligotm {
  my $seq = shift;
  my $result = `oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $seq`;
  chomp $result;
  return $result + 0;
}

# Primer constant: 5' spacer (T) + BsaI recognition (GGTCTC) + 1nt spacer (A)
my $const = "TGGTCTCA";

# Fragment definitions:
# fwd_oh = left overhang (NOT from this template, added as non-annealing tail)
# rev_oh = right overhang on top strand (FROM this template, part of annealing)
# fwd_start = template start position for forward primer annealing
# rev_end = template end position for reverse primer annealing (last base of fragment in output)
my @frags = (
  # input: circular, linearized as input[687..end]+input[0..209]
  { name => 'input', seq => $s{input}, fwd_oh => 'GGGT', rev_oh => 'ACAT',
    fwd_start => 687, rev_end => 209 },
  # egfp: egfp[0..713] (excludes TAA stop)
  { name => 'egfp', seq => $s{egfp}, fwd_oh => 'ACAT', rev_oh => 'CAAA',
    fwd_start => 0, rev_end => 713 },
  # flag: flag[3..86] (excludes ATG start and TAA stop)
  { name => 'flag', seq => $s{flag}, fwd_oh => 'CAAA', rev_oh => 'TTCA',
    fwd_start => 3, rev_end => 86 },
  # snap: snap[3..545] (excludes ATG start; TAA at 546-548 overlaps input[687-689])
  { name => 'snap', seq => $s{snap}, fwd_oh => 'TTCA', rev_oh => 'GGGT',
    fwd_start => 3, rev_end => 545 },
);

my @primers;

for my $fr (@frags) {
  my $name = $fr->{name};
  my $seq = $fr->{seq};
  my $fwd_oh = $fr->{fwd_oh};
  my $rev_oh = $fr->{rev_oh};
  my $rev_oh_rc = rev_comp($rev_oh);
  my $fwd_start = $fr->{fwd_start};
  my $rev_end = $fr->{rev_end};

  # Forward primer candidates: annealing = template[fwd_start..fwd_start+N-1]
  my @fwd_cand;
  for my $N (15..45) {
    my $anneal = substr($seq, $fwd_start, $N);
    my $tm = oligotm($anneal);
    if ($tm >= 58 && $tm <= 72) {
      push @fwd_cand, { N => $N, anneal => $anneal, tm => $tm };
    }
  }

  # Reverse primer candidates: annealing = rev_comp(template[rev_end-L+1..rev_end])
  # First 4 nt of annealing = rev_oh_rc (part of template, included in Tm)
  my @rev_cand;
  for my $L (15..45) {
    my $template_region = substr($seq, $rev_end - $L + 1, $L);
    my $anneal = rev_comp($template_region);
    my $tm = oligotm($anneal);
    if ($tm >= 58 && $tm <= 72) {
      push @rev_cand, { L => $L, anneal => $anneal, tm => $tm };
    }
  }

  printf "%s: %d fwd candidates, %d rev candidates\n", $name, scalar(@fwd_cand), scalar(@rev_cand);

  # Find best pair: minimize Tm difference, then closeness to 65°C
  my $best;
  for my $f (@fwd_cand) {
    for my $r (@rev_cand) {
      my $dtm = abs($f->{tm} - $r->{tm});
      next if $dtm > 5;
      my $score = $dtm * 100 + abs($f->{tm} - 65) + abs($r->{tm} - 65);
      if (!defined $best || $score < $best->{score}) {
        $best = { score => $score, f => $f, r => $r };
      }
    }
  }

  die "No valid primer pair for $name\n" unless $best;

  my $f = $best->{f};
  my $r = $best->{r};

  # Forward primer: [const][fwd_oh][annealing] (overhang is non-annealing)
  my $fwd_primer = $const . $fwd_oh . $f->{anneal};

  # Reverse primer: [const][annealing] (first 4 nt of annealing = overhang_rc, which IS annealing)
  my $rev_primer = $const . $r->{anneal};

  # Verify reverse overhang
  my $rev_oh_check = substr($r->{anneal}, 0, 4);
  die "Reverse overhang mismatch for $name: expected $rev_oh_rc, got $rev_oh_check\n"
    if $rev_oh_check ne $rev_oh_rc;

  # Check for internal BsaI sites
  my $fwd_ggtctc = () = ($fwd_primer =~ /GGTCTC/g);
  my $fwd_gagacc = () = ($fwd_primer =~ /GAGACC/g);
  my $rev_ggtctc = () = ($rev_primer =~ /GGTCTC/g);
  my $rev_gagacc = () = ($rev_primer =~ /GAGACC/g);
  if ($fwd_ggtctc != 1) { warn "WARNING: ${name}_fwd has $fwd_ggtctc GGTCTC sites\n" }
  if ($fwd_gagacc > 0)  { warn "WARNING: ${name}_fwd has $fwd_gagacc GAGACC sites\n" }
  if ($rev_ggtctc != 1) { warn "WARNING: ${name}_rev has $rev_ggtctc GGTCTC sites\n" }
  if ($rev_gagacc > 0)  { warn "WARNING: ${name}_rev has $rev_gagacc GAGACC sites\n" }

  push @primers, { name => $name, dir => 'fwd', seq => $fwd_primer, tm => $f->{tm},
    anneal => $f->{anneal}, anneal_len => $f->{N} };
  push @primers, { name => $name, dir => 'rev', seq => $rev_primer, tm => $r->{tm},
    anneal => $r->{anneal}, anneal_len => $r->{L} };
}

# Write primers.fasta (no blank lines)
open my $out, '>', 'primers.fasta' or die $!;
for my $p (@primers) {
  print $out ">$p->{name}_$p->{dir}\n";
  print $out "$p->{seq}\n";
}
close $out;

# Print summary
print "\n=== Primer Summary ===\n";
for my $p (@primers) {
  printf "%s_%s: len=%d anneal_len=%d tm=%.2f\n", $p->{name}, $p->{dir}, length($p->{seq}), $p->{anneal_len}, $p->{tm};
  printf "  full:    %s\n", $p->{seq};
  printf "  anneal:  %s\n", $p->{anneal};
}

# Print Tm pair check
print "\n=== Tm Pair Check ===\n";
for (my $i = 0; $i < scalar(@primers); $i += 2) {
  my $f = $primers[$i];
  my $r = $primers[$i+1];
  printf "%s: fwd_tm=%.2f rev_tm=%.2f diff=%.2f %s\n",
    $f->{name}, $f->{tm}, $r->{tm}, abs($f->{tm}-$r->{tm}),
    abs($f->{tm}-$r->{tm}) <= 5 ? "OK" : "FAIL";
}
